create table if not exists public.peserta (
  nim         text primary key,
  nama        text not null,
  kelompok    text,
  prodi       text,
  finalized   boolean not null default false,
  created_at  timestamptz not null default now()
);

create table if not exists public.nilai (
  nim    text not null references public.peserta(nim) on delete cascade,
  kode   text not null,            -- M1..M9, T1..T4, K1..K3
  nilai  numeric(5,2) not null check (nilai >= 0),
  primary key (nim, kode)
);

-- RLS aktif TANPA policy: kunci publik tidak bisa akses tabel ini.
alter table public.peserta enable row level security;
alter table public.nilai   enable row level security;

